'use strict';
const input=$input.first()?.json||{};
const findings=[];
const MAX_TEXT=64000,MAX_ARRAY=300,MAX_DEPTH=14;
const SECRET=[
 ['telegram_token',/\b\d{7,12}:[A-Za-z0-9_-]{30,}\b/g],
 ['openai_key',/\b(?:sk|sess)-[A-Za-z0-9_-]{20,}\b/g],
 ['bearer',/\bBearer\s+[A-Za-z0-9._~+\/-]{16,}\b/gi],
 ['jwt',/\beyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\b/g],
 ['credential_assignment',/\b(?:api[_ -]?key|access[_ -]?token|refresh[_ -]?token|token|secret|password|private[_ -]?key)\s*[:=]\s*[^\s,;]{8,}/gi]
];
const INJECTION=[
 ['override_policy',/(?:\b(?:ignore|disregard|forget|override|bypass)\b|(?:игнорируй|забудь|отмени|обойди|перепиши)).{0,180}(?:\b(?:previous|prior|system|developer|policy|instructions?|rules?|guardrails?)\b|(?:предыдущ|системн|разработчик|политик|инструкц|правил|ограничен))/giu],
 ['role_escalation',/(?:\b(?:you are now|act as|pretend to be|switch role|new system message)\b|(?:теперь ты|действуй как|представь что ты|смени роль|новое системное сообщение))/giu],
 ['prompt_exfiltration',/(?:\b(?:reveal|show|print|expose|dump|repeat verbatim)\b|(?:раскрой|покажи|выведи|процитируй дословно)).{0,180}(?:\b(?:system prompt|developer message|hidden instructions?|chain of thought|credentials?|api keys?|tokens?)\b|(?:системн(?:ый|ого) промпт|внутренн(?:ие|их) инструкц|секрет|ключ|токен))/giu],
 ['tool_or_runtime_control',/(?:\$env\.|\$credentials|\$node\[|\$execution\.|execute\s+(?:workflow|command|shell)|выполни\s+(?:workflow|команд|скрипт)|tool_calls?|function_call|computer_use)/giu],
 ['data_exfiltration',/(?:send|upload|post|forward|exfiltrate|отправь|загрузи|перешли).{0,120}(?:secret|credential|token|key|environment|history|memory|секрет|ключ|токен|памят|истори).{0,160}(?:https?:\/\/|webhook|endpoint|сервер|адрес)/giu],
 ['role_tag',/<\/?(?:system|assistant|developer|tool|function|instructions?)[^>]*>/giu],
 ['delimiter_breakout',/<\/(?:untrusted_[a-z_]+|user_saved_response_template|application_policy|trusted_policy)>/giu],
 ['encoded_follow',/(?:decode|base64|hex|url[- ]?decode|расшифруй|декодируй).{0,100}(?:follow|execute|obey|выполни|следуй)/giu]
];
const CONFUSABLE={'а':'a','е':'e','о':'o','р':'p','с':'c','х':'x','у':'y','к':'k','м':'m','т':'t','в':'b','н':'h','і':'i','ј':'j','ѕ':'s'};
function normalizeBase(v){return String(v??'').normalize('NFKC').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F\u200B-\u200F\u202A-\u202E\u2060\u2066-\u2069\uFEFF]/g,'').replace(/\r\n?/g,'\n');}
function skeleton(s){return [...s.toLowerCase()].map(c=>CONFUSABLE[c]||c).join('');}
function htmlDecode(s){return s.replace(/&#(x?[0-9a-f]+);?/gi,(_,n)=>{try{return String.fromCodePoint(n[0].toLowerCase()==='x'?parseInt(n.slice(1),16):parseInt(n,10))}catch{return _}}).replace(/&lt;/gi,'<').replace(/&gt;/gi,'>').replace(/&quot;/gi,'"').replace(/&#39;|&apos;/gi,"'").replace(/&amp;/gi,'&');}
function percentDecode(s){let x=s;for(let i=0;i<2;i++){try{const y=decodeURIComponent(x);if(y===x)break;x=y}catch{break}}return x;}
function base64Variants(s){const out=[];const re=/(?:^|[^A-Za-z0-9+/_=-])([A-Za-z0-9+/_-]{24,}={0,2})(?=$|[^A-Za-z0-9+/_=-])/g;let m,c=0;while((m=re.exec(s))&&c++<20){let raw=m[1].replace(/-/g,'+').replace(/_/g,'/');while(raw.length%4)raw+='=';try{const t=Buffer.from(raw,'base64').toString('utf8');if(/[\p{L}\p{N}]/u.test(t)&&!/[\u0000-\u0008]/.test(t))out.push(t.slice(0,12000));}catch{}}return out;}
function variants(s){const n=normalizeBase(s);const arr=[n,skeleton(n),htmlDecode(n),percentDecode(n)];for(const x of [...arr])arr.push(...base64Variants(x));return [...new Set(arr.map(normalizeBase))].slice(0,40);}
function scan(text,path){const vs=variants(text);const hits=[];for(const [id,re] of INJECTION){if(vs.some(v=>{re.lastIndex=0;return re.test(v)}))hits.push(id);}for(const [id,re] of SECRET){if(vs.some(v=>{re.lastIndex=0;return re.test(v)}))hits.push(id);}for(const id of [...new Set(hits)])findings.push({path,type:id,severity:SECRET.some(x=>x[0]===id)?'critical':'high'});return [...new Set(hits)];}
function redactSecrets(s){let x=s;for(const [,re] of SECRET){re.lastIndex=0;x=x.replace(re,'[REDACTED_SECRET]');}return x;}
function neutralizeEncoded(s){return s.replace(/([A-Za-z0-9+/_-]{40,}={0,2})/g,m=>{const hits=scan(m,'encoded_segment');return hits.length?'[ENCODED_UNTRUSTED_CONTENT_REMOVED]':m;}).replace(/(?:%[0-9a-f]{2}){8,}/gi,m=>scan(m,'percent_segment').length?'[ENCODED_UNTRUSTED_CONTENT_REMOVED]':m);}
function cleanString(value,path){let s=normalizeBase(value).slice(0,MAX_TEXT);const hits=scan(s,path);s=redactSecrets(s);if(hits.some(id=>!SECRET.some(x=>x[0]===id))){for(const [,re] of INJECTION){re.lastIndex=0;s=s.replace(re,'[NEUTRALIZED_UNTRUSTED_INSTRUCTION]');}s=neutralizeEncoded(s);}return s.replace(/&/g,'＆').replace(/</g,'‹').replace(/>/g,'›');}
function sanitize(v,path='root',depth=0){if(depth>MAX_DEPTH)return '[TRUNCATED_DEPTH]';if(typeof v==='string'||typeof v==='number'||typeof v==='boolean')return cleanString(v,path);if(Array.isArray(v))return v.slice(0,MAX_ARRAY).map((x,i)=>sanitize(x,`${path}[${i}]`,depth+1));if(v&&typeof v==='object'){const o={};for(const [k,x] of Object.entries(v)){if(/(?:credential|secret|password|api.?key|access.?token|refresh.?token|private.?key)$/i.test(k)){findings.push({path:`${path}.${k}`,type:'secret_field_removed',severity:'critical'});continue;}o[k]=sanitize(x,`${path}.${k}`,depth+1);}return o;}return v;}
const out={...input};
const explicit=new Set(['selectedMemoryBlock','selectedUserProfileMemoryBlock','stateSummaryBlock','tagGuidanceBlock','contextBlock','triggeredInstructionResponseText','assistantArtifactText','relevantNotes','selectedNotes','matchedTriggeredInstructions','triggeredInstructionMatches','chatHistory','profileMemory','retrievedContext','toolOutput','fileContent','knowledgeContext']);
let sanitizedFields=0;
for(const key of Object.keys(out)){if(explicit.has(key)||/(?:memory|history|retrieved|note|context|template|artifact|stateSummary|profile|toolOutput|fileContent|knowledge)/i.test(key)){out[key]=sanitize(out[key],key);sanitizedFields++;}}
out.promptSecurity={policyVersion:'chelsea_prompt_security_v3',sanitizedFields,findings:findings.slice(0,300),criticalFindings:findings.filter(f=>f.severity==='critical').length,highFindings:findings.filter(f=>f.severity==='high').length,normalization:'nfkc_controls_bidi_strip_confusable_scan_html_percent_base64_scan',neutralized:true,validatedAtIso:new Date().toISOString()};
out.promptSecurityReady=true;
return [{json:out}];
